/* Événements des variantes d'école, de passion et d'adolescence : issues courtes. */
const GENERIC_T=(label,note)=>label;
function stripFx(x){x._fx=x.fx;x.fx={}}
function outcomeEvent(s,p,e,x,i,def,res,prob){return{id:'out-'+e.id,title:'Ce qui s’est passé',text:res.text,category:e.category,required:true,tone:res.ok?'good':'bad',stats:prob!=null?[{label:'Chances que ça se passe bien',pct:Math.round(prob*100),p:prob,strong:true,src:'jeu'}]:[],statsKicker:'Ce que disait le modèle',choices:[{label:'Continuer',note:'',fx:res.fx||{}}]}}
L.choose=function(s,i){const e=s.pending,x=e?.choices?.[i],defs=e&&OUT[e.id],def=defs?.[i];
  if(!e||!x||!def||x.fx?.struggle||x.fx?.chain){return base.choose(s,i)}
  const reason=L.canChoose(s,x);if(reason)return base.choose(s,i);
  const p=s.person,age=p.age;let result=null,prob=null;
  if(def.p){const c=ctxOf(s,p);prob=clamp(def.p(c),.03,.97);const ok=hash(s.seed,p.id,'outcome',e.id,s.year,i)<prob;result={ok,...(ok?def.ok:def.ko)};if(def.strip&&!def.keep)stripFx(x)}
  const r=base.choose(s,i);if(!r)return r;
  const label=x.label;const last=s.journal.at(-1);
  if(result){const line=`${e.title} — ${label}.`;if(last&&last.text.startsWith(e.title+' — '))last.text=line;L.log(s,result.text,true,'life');s.queue??=[];s.queue.unshift(outcomeEvent(s,p,e,x,i,def,result,prob));if(!s.pending&&s.queue.length&&p.alive)s.pending=s.queue.shift()}
  else{const text=def.t;if(last&&last.text.startsWith(e.title+' — '))last.text=`${e.title} — ${label}. ${text}`;s.notice={text,year:s.year,tone:'plain',title:e.title}}
  return r};
/* Suite d'un écran « Ce qui s'est passé » : effets particuliers (arrêt de l'école…) */
const prevChoose=L.choose;L.choose=function(s,i){const e=s.pending,x=e?.choices?.[i];const r=prevChoose(s,i);if(r&&e?.id?.startsWith('out-')){const p=s.person,fx=x?.fx||{};if(fx.quitSchool){p.school??={level:L.schoolLevel(p),history:[]};p.school.stopped=true}for(let k=s.journal.length-1;k>=Math.max(0,s.journal.length-6);k--)if(s.journal[k].text.startsWith(e.title+' — ')){s.journal.splice(k,1);break}s.notice=null}else if(r&&!s.pending&&s.notice&&s.notice.year!==s.year)s.notice=null;return r};
L.outcomes=OUT;
